const N_MAX = 5e5; // 500 mil partículas para melhor performance

let sh;
let attribs;
let gl;
let canvasGL, W, H;
let ping, pong;

function preload() {
  sh = loadShader('https://openprocessing.org/sketch/2698618/files/vert.glsl', 'frag.glsl');

  attribs = {
    poss: new Float32Array(N_MAX * 2).map(() => random() * 2 - 1),
    vels: new Float32Array(N_MAX * 2),
  };

  document.addEventListener('contextmenu', e => e.preventDefault());
}

p5.RendererGL.prototype._initContext = function () {
  this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes);
  if (!this.drawingContext) alert('Failed to initialize WebGL2');
  gl = this.drawingContext;
};

function setup() {
  W = windowWidth;
  H = windowHeight;
  canvasGL = createCanvas(W, H, WEBGL);
  gl.viewport(0, 0, W, H);
  canvasGL._viewport = gl.getParameter(gl.VIEWPORT);

  pixelDensity(1);
  ping = createBufferSet();
  pong = createBufferSet();

  const linkOriginal = gl.linkProgram;
  Object.defineProperty(gl, 'linkProgram', {
    get: () => {
      gl.transformFeedbackVaryings(sh._glProgram, ['v_p', 'v_v'], gl.SEPARATE_ATTRIBS);
      gl.linkProgram = linkOriginal;
      return linkOriginal;
    },
  });

  // Configura blend e desativa profundidade e cull uma vez só para performance
  gl.disable(gl.DEPTH_TEST);
  gl.disable(gl.CULL_FACE);
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);

  shader(sh);
  rect(0, 0, 0, 0);

  frameRate(60); // Limita o FPS para 30 para aliviar GPU
}

function createBufferSet() {
  const vao = gl.createVertexArray();
  gl.bindVertexArray(vao);

  const vbo_p = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, vbo_p);
  gl.bufferData(gl.ARRAY_BUFFER, attribs.poss, gl.DYNAMIC_DRAW);
  gl.enableVertexAttribArray(0);
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

  const vbo_v = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, vbo_v);
  gl.bufferData(gl.ARRAY_BUFFER, attribs.vels, gl.DYNAMIC_DRAW);
  gl.enableVertexAttribArray(1);
  gl.vertexAttribPointer(1, 2, gl.FLOAT, false, 0, 0);

  const xfb = gl.createTransformFeedback();
  gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, xfb);
  gl.bindBufferBase(gl.TRANSFORM_FEEDBACK_BUFFER, 0, vbo_p);
  gl.bindBufferBase(gl.TRANSFORM_FEEDBACK_BUFFER, 1, vbo_v);

  gl.bindVertexArray(null);
  gl.bindBuffer(gl.ARRAY_BUFFER, null);
  gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, null);

  return { vao, xfb };
}

function pingpong() {
  [ping, pong] = [pong, ping];
}

function draw() {
  // Ajusta o número de partículas processadas conforme o FPS para manter fluidez
  const targetFPS = 60;
  const currentFPS = frameRate();
  const ratio = constrain(currentFPS / targetFPS, 0.1, 1);
  const n = Math.floor(N_MAX * ratio);

  gl.clearColor(0.05, 0.05, 0.1, 1);
  gl.clear(gl.COLOR_BUFFER_BIT);

  shader(sh);

  sh.setUniform('time', millis());
  sh.setUniform('asp', H / W);

  // Calcular a posição e botões no JS para evitar branch no shader
  let mooseX, mooseY;
  let buttsArr;
  if (frameCount < 500) {
    mooseX = (random() * 2 - 1) * W / H;
    mooseY = random() * 2 - 1;
    buttsArr = [true, false, false, 0];
  } else {
    mooseX = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / W) * 2 - 1;
    mooseX *= W / H;
    mooseY = (1 - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / H) * 2 - 1;
    buttsArr = [
      ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton === LEFT,
      ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton === CENTER,
      ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton === RIGHT,
      0,
    ];
  }

  sh.setUniform('moose', [mooseX, mooseY]);
  sh.setUniform('butts', buttsArr);

  gl.bindVertexArray(ping.vao);
  gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, pong.xfb);
  gl.beginTransformFeedback(gl.POINTS);
  gl.drawArrays(gl.POINTS, 0, n);
  gl.endTransformFeedback();
  gl.bindVertexArray(null);

  pingpong();
}


