layout(location=0) in vec2 in_p;
layout(location=1) in vec2 in_v;
out vec2 v_p;
out vec2 v_v;
flat out vec4 v_c;
void main(){

	//worldspace
	vec2 p= in_p;
	vec2 v= in_v;

	//kinesis
	vec2 o= vec2(moose); //attractor
	vec2 d= p-o; //delta position
	float l= max(.01,len(d+ETA));
	float g= 1./l; //gravity

	//buttons
	if(butts.x!=0)
		g= g*g/4.;
	if(butts.z!=0)
		g= 1./(g*g);

	//impulse
	vec2 j= norm(-d)*g*G;

	//integral, forward euler
	v+= j;
	p+= v;

	//boundary
	if(len(p)>2.5){
		p*= .025;
		v*= .25;
	}

	//xfeed out
	v_v= v;
	v_p= p;

	//projspace far:+z up:+y
	vec4 w= vec4(p,.5,FOV);
	w.x*= asp;
  gl_Position= w;//renegade lack of mvp

  gl_PointSize= BIGNESS;

	//vec4 col= vec4(in_c,1.);

	float h= len(v+ETA);
